function createOsDataSheet_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var existing = ss.getSheetByName('OS_DATA');
  if (existing) {
    existing.clearContents();
  } else {
    existing = ss.insertSheet('OS_DATA');
  }
  // Set header
  existing.getRange(1, 1, 1, 6).setValues([
    ['os_key', 'Passport No', 'Pax Name', 'Supposed to Contain', 'Associated BR', 'Items Cleared Under BR']
  ]);
  existing.setFrozenRows(1);
  // Style header
  existing.getRange(1, 1, 1, 6)
    .setBackground('#1a73e8').setFontColor('#ffffff').setFontWeight('bold');
  return existing;
}

function loadAllOsData() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = createOsDataSheet_();
  var startRow = 2;
  startRow = loadChunk_(getData_00_, sheet, startRow);
  startRow = loadChunk_(getData_01_, sheet, startRow);
  startRow = loadChunk_(getData_02_, sheet, startRow);
  startRow = loadChunk_(getData_03_, sheet, startRow);
  startRow = loadChunk_(getData_04_, sheet, startRow);
  startRow = loadChunk_(getData_05_, sheet, startRow);
  startRow = loadChunk_(getData_06_, sheet, startRow);
  startRow = loadChunk_(getData_07_, sheet, startRow);
  startRow = loadChunk_(getData_08_, sheet, startRow);
  startRow = loadChunk_(getData_09_, sheet, startRow);
  startRow = loadChunk_(getData_10_, sheet, startRow);
  startRow = loadChunk_(getData_11_, sheet, startRow);
  startRow = loadChunk_(getData_12_, sheet, startRow);
  startRow = loadChunk_(getData_13_, sheet, startRow);
  startRow = loadChunk_(getData_14_, sheet, startRow);
  startRow = loadChunk_(getData_15_, sheet, startRow);
  startRow = loadChunk_(getData_16_, sheet, startRow);
  startRow = loadChunk_(getData_17_, sheet, startRow);
  startRow = loadChunk_(getData_18_, sheet, startRow);
  startRow = loadChunk_(getData_19_, sheet, startRow);
  startRow = loadChunk_(getData_20_, sheet, startRow);
  startRow = loadChunk_(getData_21_, sheet, startRow);
  startRow = loadChunk_(getData_22_, sheet, startRow);
  startRow = loadChunk_(getData_23_, sheet, startRow);

  // Auto-resize columns
  sheet.autoResizeColumn(1);
  sheet.autoResizeColumn(2);
  sheet.autoResizeColumn(3);
  // Wrap text for items columns
  sheet.getRange(2, 4, sheet.getLastRow()-1, 3).setWrap(true);
  // Hide this sheet
  sheet.hideSheet();
  SpreadsheetApp.getUi().alert('OS_DATA loaded: 11602 records.\nNow run setupMainSheetFormulas()');
}

function loadChunk_(dataFn, sheet, startRow) {
  var data = dataFn();
  if (data.length > 0) {
    sheet.getRange(startRow, 1, data.length, 6).setValues(data);
    SpreadsheetApp.flush();
  }
  return startRow + data.length;
}

